import { spawnSync } from "node:child_process";

const repoRoot = "/Users/antonio/Email GTM Infra";
const sandboxRunId = process.env.GROWTHUB_SANDBOX_RUN_ID || Date.now().toString(36);
const queuePlan = {
  "sourceObjectId": "twenty-crm-people",
  "totalRowsAtSetup": 18807,
  "provenContactsClosed": 500,
  "provenQueueSize": 250,
  "batchSize": 50,
  "batchesPerQueue": 5,
  "nextQueueStartOffset": 500,
  "builderSmokeLimit": 1,
  "builderSmokeOffset": 500,
  "applyDefault": false
};
const runId = `workflow-official-table-smoke-${sandboxRunId}`;
const outPath = `/tmp/email-gtm-reacher-${runId}.json`;
const args = [
  "tools/twenty-official-table-enrichment-workflow.mjs",
  "--limit", String(queuePlan.builderSmokeLimit),
  "--offset", String(queuePlan.builderSmokeOffset),
  "--run-id", runId,
  "--out", outPath
];
const result = spawnSync("node", args, {
  cwd: repoRoot,
  encoding: "utf8",
  env: process.env,
  maxBuffer: 1024 * 1024 * 8
});
const stdout = result.stdout || "";
const stderr = result.stderr || "";
const summary = {
  ok: result.status === 0,
  workflow: "official-table-enrichment",
  mode: "builder-smoke-dry-run",
  queuePlan,
  sourceObjectId: "twenty-crm-people",
  sandboxObjectId: "email-gtm-infra-sandboxes",
  tool: "tools/twenty-official-table-enrichment-workflow.mjs",
  limit: queuePlan.builderSmokeLimit,
  offset: queuePlan.builderSmokeOffset,
  apply: false,
  runId,
  outPath,
  exitCode: result.status,
  signal: result.signal || null,
  stdoutTail: stdout.slice(-12000),
  stderrTail: stderr.slice(-12000)
};
console.log(JSON.stringify(summary, null, 2));
if (result.status !== 0) process.exit(result.status || 1);

