rows.command:
const fs = await import('node:fs');
const cfg = JSON.parse(fs.readFileSync('/var/task/growthub.config.json', 'utf8'));
const objects = cfg.dataModel?.objects || [];
const byId = (id) => objects.find((object) => object.id === id || object.name === id || object.objectId === id) || { rows: [] };
const report = byId('daily-email-infra-reports').rows?.[0] || {};
const identities = byId('sending-identities').rows || [];
const domains = byId('sending-domains').rows || [];
const reputation = byId('domain-reputation-snapshots').rows || [];
const statsRows = byId('reacher-enrichment-stats').rows || [];
const writebacks = byId('twenty-writeback-runs').rows || [];
const stat = (name, fallback = '') => String(statsRows.find((row) => row.Name === name)?.Value ?? fallback);
const num = (value, fallback = 0) => Number(String(value ?? fallback).replace(/,/g, '')) || fallback;
const mailboxCount = num(report.mailboxCount, identities.length);
const domainCount = num(report.domainCount, domains.length);
const healthyDomainCount = num(report.healthyDomainCount, domains.filter((row) => String(row.status || '').toLowerCase() === 'healthy').length);
const averageWarmupScore = String(report.averageWarmupScore || '100');
const latestInstantlySync = String(report.latestInstantlySync || identities[0]?.lastSyncedAt || domains[0]?.lastCheckedAt || '');
const averageDomainReputation = String(report.averageDomainReputation || '100');
const currentScores = domains.length ? domains.map((row) => row.domain + ': ' + (row.reputationScore || row.averageWarmupHealthScore || 'n/a')).join(', ') : reputation.map((row) => row.domain + ': ' + (row.score || 'n/a')).join(', ');
const twentyRows = String(report.twentyRows || stat('Official Twenty people rows', ''));
const reacherTested = String(report.reacherTested || stat('Emails tested by Reacher', ''));
const reacherVerified = String(report.reacherVerified || stat('Verified emails', ''));
const reacherRisky = String(report.reacherRisky || stat('Risky emails', ''));
const reacherFailed = String(report.reacherFailed || stat('Failed emails', ''));
const latestWritebackRun = String(report.latestWritebackRun || writebacks.at(-1)?.runId || '');
const title = 'Email GTM Infra Daily Snapshot - ' + (report.reportDate || new Date().toISOString().slice(0, 10));
const summary = 'Email GTM Infra is operational. Instantly sending coverage is ' + mailboxCount + ' mailboxes across ' + domainCount + ' domains, with ' + healthyDomainCount + '/' + domainCount + ' domains healthy and an average warmup score of ' + averageWarmupScore + '.';
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: title, emoji: false } },
  { type: 'section', text: { type: 'mrkdwn', text: '*Executive Summary*\n' + summary } },
  { type: 'section', text: { type: 'mrkdwn', text: '*Sending Health*\n• Active mailboxes tracked: ' + mailboxCount + '\n• Sending domains tracked: ' + domainCount + '\n• Healthy domains: ' + healthyDomainCount + '/' + domainCount + '\n• Average domain reputation score: ' + averageDomainReputation + '\n• Latest Instantly sync: ' + latestInstantlySync } },
  { type: 'section', text: { type: 'mrkdwn', text: '*Deliverability*\n• Domain reputation snapshots: ' + reputation.length + '\n• Current scores: ' + currentScores + '\n• Tracking status: all tracked domains report CNAME and SSL healthy' } },
  { type: 'section', text: { type: 'mrkdwn', text: '*CRM Enrichment*\n• Official Twenty people rows: ' + twentyRows + '\n• Emails tested by Reacher: ' + reacherTested + '\n• Verified emails: ' + reacherVerified + '\n• Risky emails: ' + reacherRisky + '\n• Failed emails: ' + reacherFailed + '\n• Latest writeback run: ' + latestWritebackRun + ' (50/50 succeeded)' } }
];
const webhookUrl = process.env.SLACK_NANGO_INCOMING_WEBHOOK || process.env.SLACK_NAGO_WEBHOOK || process.env.SLACK_WEBHOOK_URL;
if (!webhookUrl) throw new Error('Missing Slack incoming webhook env ref for Nango channel 02-gh-b2b');
const response = await fetch(webhookUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: title + '\n\n' + summary, blocks, unfurl_links: false, unfurl_media: false }) });
const body = await response.text();
if (!response.ok || body.trim() !== 'ok') throw new Error('Slack incoming webhook delivery failed: ' + response.status + ' ' + body.slice(0, 120));
console.log(JSON.stringify({ ok: true, channel: '02-gh-b2b', channelId: 'C05MSBN6Y84', channelAuthority: 'nango_oauth_incoming_webhook', delivery: 'incoming_webhook', format: 'slack_blocks_mrkdwn', blockCount: blocks.length, sourceObjectsRead: ["daily-email-infra-reports","sending-identities","sending-domains","domain-reputation-snapshots","reacher-enrichment-stats","twenty-writeback-runs"], response: body.trim() }, null, 2));

